/* CHỈ VP, không dùng cho silicon. */
#define NEON_FX1_SIM_CTRL_BASE 0x10020000u
/* Ghi 0x5555 PASS; ghi (code << 16) | 0x3333 FAIL. */
#define NEON_FX1_SIM_CTRL_FINISH_OFFSET 0x00000000u
#define NEON_FX1_SIM_CTRL_FINISH_ACCESS NEON_FX1_ACCESS_WO
#define NEON_FX1_SIM_CTRL_FINISH_RESET_KNOWN 0u
#define NEON_FX1_SIM_CTRL_FINISH_RO_MASK 0x00000000u
#define NEON_FX1_SIM_CTRL_FINISH_RW_MASK 0x00000000u
#define NEON_FX1_SIM_CTRL_FINISH_W1C_MASK 0x00000000u
#define NEON_FX1_SIM_CTRL_FINISH_W1S_MASK 0x00000000u
#define NEON_FX1_SIM_CTRL_FINISH_W1P_MASK 0x00000000u
#define NEON_FX1_SIM_CTRL_FINISH_W1SC_MASK 0x00000000u
#define NEON_FX1_SIM_CTRL_FINISH_UNKNOWN_MASK 0x00000000u
#define NEON_FX1_SIM_CTRL_FINISH_WO_MASK 0xFFFFFFFFu
/* Bit 0..2 điều khiển nguồn test PLIC 4..6. */
#define NEON_FX1_SIM_CTRL_IRQ_OFFSET 0x00000004u
#define NEON_FX1_SIM_CTRL_IRQ_ACCESS NEON_FX1_ACCESS_RW
#define NEON_FX1_SIM_CTRL_IRQ_RESET_KNOWN 0u
/*  */
#define NEON_FX1_SIM_CTRL_IRQ_TEST_LINES_SHIFT 0u
#define NEON_FX1_SIM_CTRL_IRQ_TEST_LINES_WIDTH 3u
#define NEON_FX1_SIM_CTRL_IRQ_TEST_LINES_MASK 0x00000007u
#define NEON_FX1_SIM_CTRL_IRQ_TEST_LINES_ACCESS NEON_FX1_ACCESS_RW
#define NEON_FX1_SIM_CTRL_IRQ_RO_MASK 0x00000000u
#define NEON_FX1_SIM_CTRL_IRQ_RW_MASK 0x00000007u
#define NEON_FX1_SIM_CTRL_IRQ_W1C_MASK 0x00000000u
#define NEON_FX1_SIM_CTRL_IRQ_W1S_MASK 0x00000000u
#define NEON_FX1_SIM_CTRL_IRQ_W1P_MASK 0x00000000u
#define NEON_FX1_SIM_CTRL_IRQ_W1SC_MASK 0x00000000u
#define NEON_FX1_SIM_CTRL_IRQ_UNKNOWN_MASK 0x00000000u
#define NEON_FX1_SIM_CTRL_IRQ_WO_MASK 0x00000000u
typedef struct {
    volatile uint32_t FINISH; /* 0x0000, wo */
    volatile uint32_t IRQ; /* 0x0004, rw */
} NEON_FX1_SIM_CTRL_Regs_t;
#define NEON_FX1_SIM_CTRL ((NEON_FX1_SIM_CTRL_Regs_t *)(uintptr_t)NEON_FX1_SIM_CTRL_BASE)
NEON_FX1_OFFSET_ASSERT(offsetof(NEON_FX1_SIM_CTRL_Regs_t, FINISH) == NEON_FX1_SIM_CTRL_FINISH_OFFSET, "SIM_CTRL.FINISH");
NEON_FX1_OFFSET_ASSERT(offsetof(NEON_FX1_SIM_CTRL_Regs_t, IRQ) == NEON_FX1_SIM_CTRL_IRQ_OFFSET, "SIM_CTRL.IRQ");
#define NEON_FX1_SIM_CTRL_REGISTER_COUNT 2u
#define NEON_FX1_SIM_CTRL_REGISTER_LIST(X) \
    X(FINISH, 0x00000000u, NEON_FX1_ACCESS_WO) \
    X(IRQ, 0x00000004u, NEON_FX1_ACCESS_RW) \
    /* hết danh sách */

